<template><div class="item" :class="{selected}" @click="$emit('click')" @dblclick="$emit('open')"><span class="file-icon"><span class="icon">{{icon}}</span></span><span class="name">{{name}}</span><span class="type">{{type}}</span><span class="modified">{{modified||"—"}}</span><button ref="moreButton" class="more" type="button" title="More actions" aria-label="More actions" @click.stop="emitMore"><span></span><span></span><span></span></button></div></template>
